def dispatch_tool(user, tenant, tool_name, args, consent, scopes):
    if tool_name not in consent: raise PermissionError('consent required')
    if 'orders:read' not in scopes: raise PermissionError('scope missing')
    if 'tenant_id' in args: raise PermissionError('tenant is host-owned')
    return order_lookup({**args, 'tenant_id': tenant, 'user_id': user})
